<?php
require_once "../includes/auth.php";require_login("faculty");require_once "../config/db.php";$fid=$_SESSION["user"]["id"];
if(isset($_POST["save"])){ $sid=(int)$_POST["student_id"];$cid=(int)$_POST["course_id"];$marks=(float)$_POST["marks"];$grade=$_POST["grade"];$q=$conn->prepare("SELECT id FROM courses WHERE id=? AND faculty_id=?");$q->bind_param("ii",$cid,$fid);$q->execute();if($q->get_result()->num_rows){$s=$conn->prepare("INSERT INTO results(student_id,course_id,marks,grade) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE marks=VALUES(marks),grade=VALUES(grade)");$s->bind_param("iids",$sid,$cid,$marks,$grade);$s->execute();}}
$courses=$conn->prepare("SELECT id,course_code FROM courses WHERE faculty_id=?");$courses->bind_param("i",$fid);$courses->execute();$courses=$courses->get_result();$students=$conn->query("SELECT id,full_name,student_id FROM users WHERE role='student' ORDER BY full_name");$page_title="Results";$css_path="../assets/css/style.css";$js_path="../assets/js/main.js";require "../includes/header.php";?>
<div class="dashboard"><aside class="sidebar"><?php include "sidebar.php"; ?></aside><main class="dash-main"><h1>Enter Results</h1><div class="panel"><form method="POST" class="form-grid"><select name="student_id" required><option value="">Student</option><?php while($s=$students->fetch_assoc()):?><option value="<?=$s["id"]?>"><?=e($s["student_id"]." - ".$s["full_name"])?></option><?php endwhile;?></select><select name="course_id" required><option value="">My course</option><?php while($c=$courses->fetch_assoc()):?><option value="<?=$c["id"]?>"><?=e($c["course_code"])?></option><?php endwhile;?></select><input type="number" step=".01" min="0" max="100" name="marks" placeholder="Marks" required><select name="grade"><option>A+</option><option>A</option><option>A-</option><option>B+</option><option>B</option><option>C+</option><option>C</option><option>D</option><option>F</option></select><button name="save" class="btn btn-primary">Save Result</button></form></div></main></div><?php require "../includes/footer.php"; ?>